// test_emitter.cpp — unit tests for the M9 C++ emitter.
//
// The emitter is the last module in the transpiler pipeline:
//
//   M7 matcher  →  M8 synthesize  →  M9 emit  →  file on disk
//
// These tests exercise two layers:
//
//   1. Golden snapshot — drive the full emit() call on the PRD's MVP input
//      using a real Clang SourceManager + Rewriter produced via LibTooling.
//      Compare the generated bytes against the locked canonical form so any
//      regression in the emitter's whitespace or header pops up immediately.
//
//   2. Idempotency — take the emitter's output, feed it back through the
//      pipeline's skip-detection layer (should_skip, from M5's skip
//      module), and confirm the file is treated as pass-through. This is
//      PRD AC #5 checked at the unit level.
//
// Pure-string helpers (`idempotency_header` and `should_skip`) live in
// M5's skip module and are covered by test_skip.cpp; this file depends on
// them via #include but does not retest their standalone behavior.
//
// The tests assemble a tiny qbool stub inline so no external STURM include
// path is required. All SourceManager traffic happens inside
// `runToolOnCodeWithArgs`, matching the test_matcher.cpp pattern.

#include "sturm/transpile/emitter.hpp"
#include "sturm/transpile/io.hpp"
#include "sturm/transpile/matcher.hpp"
#include "sturm/transpile/qir.hpp"
#include "sturm/transpile/skip.hpp"
#include "sturm/transpile/uncompute_pass.hpp"

#include "clang/AST/ASTConsumer.h"
#include "clang/AST/ASTContext.h"
#include "clang/AST/Decl.h"
#include "clang/ASTMatchers/ASTMatchFinder.h"
#include "clang/ASTMatchers/ASTMatchers.h"
#include "clang/Basic/SourceLocation.h"
#include "clang/Basic/SourceManager.h"
#include "clang/Frontend/CompilerInstance.h"
#include "clang/Frontend/FrontendActions.h"
#include "clang/Frontend/PCHContainerOperations.h"
#include "clang/Rewrite/Core/Rewriter.h"
#include "clang/Tooling/Tooling.h"

#include <cassert>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <functional>
#include <memory>
#include <sstream>
#include <string>
#include <string_view>
